import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {AIRecommendation} from '../../src/AIRecommendation';import {UiLanguageProvider,LanguageSwitcher} from '../../src/ui-language';import {setBetaSession} from '../../src/beta-session';import {SessionBoundary} from '../../src/BetaAccount';
function Fixture(){const [id,setId]=useState('generation-one');return <UiLanguageProvider><LanguageSwitcher/><button onClick={()=>setId('generation-two')}>Switch saved image</button><button onClick={()=>setBetaSession(null)}>Logout fixture</button><a href="data:text/plain,unchanged-image" download="ad.txt">Original export fixture</a><SessionBoundary><AIRecommendation binding={{generationId:id,artifactHash:'a'.repeat(64)}}/></SessionBoundary></UiLanguageProvider>;}
createRoot(document.getElementById('fixture')!).render(<Fixture/>);
